        while (curr != null) {
            if (!first)
                System.out.print(" ");

            System.out.print(curr.data);
            first = false;
            curr = curr.next;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        Node head = null, tail = null;

        while (sc.hasNextInt()) {
            int x = sc.nextInt();
            Node newNode = new Node(x);

            if (head == null) {
                head = newNode;
                tail = newNode;
            } else {
                tail.next = newNode;
                tail = newNode;
            }
        }

        printList(head);
    }
}

