class ListNode {
    int val;
    ListNode next;

    ListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

class TreeNode {
    int val;
    TreeNode left, right;

    TreeNode(int val) {
        this.val = val;
        this.left = null;
        this.right = null;
    }
}

public class Solution {

    static ListNode buildList(int[] arr) {
        ListNode head = null, tail = null;

        for (int x : arr) {
            ListNode node = new ListNode(x);

            if (head == null) {
                head = node;
                tail = node;
            } else {
                tail.next = node;
                tail = node;
            }
        }

        return head;
    }

    static TreeNode buildTree(String[] values) {
        if (values.length == 0 || values[0].equals("null") || values[0].isEmpty())
            return null;

        TreeNode root = new TreeNode(Integer.parseInt(values[0].trim()));
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);

        int i = 1;

        while (!q.isEmpty() && i < values.length) {
            TreeNode node = q.poll();

            if (i < values.length &&
                !values[i].trim().equals("null") &&
                !values[i].trim().isEmpty()) {

                node.left = new TreeNode(Integer.parseInt(values[i].trim()));
                q.offer(node.left);
            }
            i++;

            if (i < values.length &&
                !values[i].trim().equals("null") &&
                !values[i].trim().isEmpty()) {

                node.right = new TreeNode(Integer.parseInt(values[i].trim()));
                q.offer(node.right);
            }
            i++;
        }

        return root;
    }

    static boolean dfs(ListNode head, TreeNode node) {
        if (head == null) return true;
        if (node == null) return false;
        if (head.val != node.val) return false;

        return dfs(head.next, node.left) ||
               dfs(head.next, node.right);
    }

    static boolean isSubPath(ListNode head, TreeNode root) {
        if (root == null) return false;

        return dfs(head, root) ||
               isSubPath(head, root.left) ||
               isSubPath(head, root.right);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();

        String[] parts = s.split(", tree:");

        String listPart = parts.length > 0
                ? parts[0].split("list:", 2)[1].trim()
                : "";

        String treePart = parts.length > 1
                ? parts[1].trim()
                : "";

        int[] listValues;

        if (listPart.isEmpty()) {
            listValues = new int[0];
        } else {
            String[] a = listPart.split("\\s+");
            listValues = new int[a.length];

            for (int i = 0; i < a.length; i++)
                listValues[i] = Integer.parseInt(a[i]);
        }

        if (treePart.startsWith("[") && treePart.endsWith("]")) {
            treePart = treePart.substring(1, treePart.length() - 1);
        }

        String[] treeValues = treePart.isEmpty()
                ? new String[0]
                : treePart.split(",");

        ListNode head = buildList(listValues);
        TreeNode root = buildTree(treeValues);

        System.out.print(isSubPath(head, root) ? "true" : "false");
    }
}

