char* trim(char* s) {
    while (isspace((unsigned char)*s))
        s++;

    char* end = s + strlen(s) - 1;

    while (end >= s && isspace((unsigned char)*end)) {
        *end = '\0';
        end--;
    }

    return s;
}

struct ListNode* appendList(struct ListNode* head, int val) {
    struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;

    if (head == NULL)
        return node;

    struct ListNode* temp = head;

    while (temp->next)
        temp = temp->next;

    temp->next = node;

    return head;
}

struct TreeNode* newTreeNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

bool dfs(struct ListNode* head, struct TreeNode* node) {
    if (head == NULL)
        return true;

    if (node == NULL)
        return false;

    if (head->val != node->val)
        return false;

    return dfs(head->next, node->left) ||
           dfs(head->next, node->right);
}

bool isSubPath(struct ListNode* head, struct TreeNode* root) {
    if (root == NULL)
        return false;

    return dfs(head, root) ||
           isSubPath(head, root->left) ||
           isSubPath(head, root->right);
}

struct TreeNode* buildTree(char* values[], int n) {
    if (n == 0 || strcmp(values[0], "null") == 0)
        return NULL;

    struct TreeNode* root = newTreeNode(atoi(values[0]));

    struct TreeNode* queue[1000];
    int front = 0, rear = 0;

    queue[rear++] = root;

    int i = 1;

    while (front < rear && i < n) {
        struct TreeNode* curr = queue[front++];

        if (i < n && strcmp(values[i], "null") != 0) {
            curr->left = newTreeNode(atoi(values[i]));
            queue[rear++] = curr->left;
        }
        i++;

        if (i < n && strcmp(values[i], "null") != 0) {
            curr->right = newTreeNode(atoi(values[i]));
            queue[rear++] = curr->right;
        }
        i++;
    }

    return root;
}

