int isSorted(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        if (arr[i] < arr[i - 1]) {
            return 0;
        }
    }
    return 1;
}

int solve(int arr[], int n) {
    if (n <= 1 || isSorted(arr, n)) {
        return 0;
    }

    int best = n / 2;

    for (int i = 0; i < n - 1; i++) {
        int *next = (int *)malloc((n - 2) * sizeof(int));
        int idx = 0;

        for (int j = 0; j < n; j++) {
            if (j == i || j == i + 1) continue;
            next[idx++] = arr[j];
        }

        int ops = 1 + solve(next, n - 2);
        if (ops < best) {
            best = ops;
        }

        free(next);
    }

    return best;
}

