    }

    int n = total - 1;
    int *arr = (int *)malloc(n * sizeof(int));

    for (int i = 1; i < total; i++) {
        arr[i - 1] = input[i];
    }

    printf("%d", solve(arr, n));

    free(arr);
    return 0;
}

