public:
    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void update(int idx, int val) {
        while (idx <= n) {
            bit[idx] = max(bit[idx], val);
            idx += idx & -idx;
        }
    }

    int query(int idx) {
        int ans = 0;
        while (idx > 0) {
            ans = max(ans, bit[idx]);
            idx -= idx & -idx;
        }
        return ans;
    }
};

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();

        vector<int> vals = nums;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());

        Fenwick oddTree(vals.size()), evenTree(vals.size());

        int bestKeep = (n % 2 == 0 ? 0 : 1);

        for (int i = 0; i < n; i++) {
            int pos = lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin() + 1;
            int dp = 0;
            int indexParity = (i + 1) % 2;

            if (indexParity == 1) {
                dp = max(1, evenTree.query(pos) + 1);
                oddTree.update(pos, dp);
            } else {
                dp = oddTree.query(pos);
                if (dp > 0) {
                    dp++;
                    evenTree.update(pos, dp);
                }
            }

            if (((i + 1) % 2) == (n % 2)) {
                bestKeep = max(bestKeep, dp);
            }
        }

        return (n - bestKeep) / 2;
    }
};

