        while ((line = br.readLine()) != null) {
            input.append(line);
        }

        List<Integer> nums = extractNumbers(input.toString());

        if (nums.isEmpty()) return;

        int appendVal = nums.get(nums.size() - 1);

        ListNode head = null;
        ListNode tail = null;

        for (int i = 0; i < nums.size() - 1; i++) {

            ListNode node = new ListNode(nums.get(i));

            if (head == null) {
                head = node;
                tail = node;
            }
            else {
                tail.next = node;
                tail = node;
            }
        }

        Solution sol = new Solution();
        head = sol.appendNode(head, appendVal);

        ListNode temp = head;

        while (temp != null) {
            System.out.print(temp.val);
            if (temp.next != null) System.out.print(" ");
            temp = temp.next;
        }
    }
}

