    public ListNode mergeInBetween(ListNode list1, int start, int end, ListNode list2) {
        ListNode prevA = list1;
        for (int i = 0; i < start - 1; i++) {
            prevA = prevA.next;
        }

        ListNode afterB = prevA;
        for (int i = 0; i < (end - start + 2); i++) {
            afterB = afterB.next;
        }

        prevA.next = list2;

        ListNode tail2 = list2;
        while (tail2.next != null) {
            tail2 = tail2.next;
        }

        tail2.next = afterB;
        return list1;
    }

    static List<Integer> extractSectionNumbers(String s, String key) {
        List<Integer> nums = new ArrayList<>();
        int pos = s.indexOf(key);
        if (pos == -1) return nums;

        pos += key.length();

        while (pos < s.length()) {
            if (s.startsWith("start:", pos) || s.startsWith("end:", pos) || s.startsWith("list2:", pos)) {
                break;
            }

            char ch = s.charAt(pos);
            if (Character.isDigit(ch) || (ch == '-' && pos + 1 < s.length() && Character.isDigit(s.charAt(pos + 1)))) {
                int sign = 1;
                if (ch == '-') {
                    sign = -1;
                    pos++;
                }

                int val = 0;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                    val = val * 10 + (s.charAt(pos) - '0');
                    pos++;
                }

                nums.add(sign * val);
            } else {
                pos++;
            }
        }

        return nums;
    }

    static int extractSingleValue(String s, String key) {
        int pos = s.indexOf(key);
        if (pos == -1) return 0;

        pos += key.length();
        while (pos < s.length() && !Character.isDigit(s.charAt(pos)) && s.charAt(pos) != '-') {
            pos++;
        }

        int sign = 1;
        if (pos < s.length() && s.charAt(pos) == '-') {
            sign = -1;
            pos++;
        }

        int val = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            val = val * 10 + (s.charAt(pos) - '0');
            pos++;
        }

        return sign * val;
    }

    static ListNode buildList(List<Integer> nums) {
        ListNode head = null;
        ListNode tail = null;

        for (int x : nums) {
            ListNode node = new ListNode(x);
            if (head == null) {
                head = tail = node;
            } else {
                tail.next = node;
                tail = node;
            }
        }

        return head;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            if (input.length() > 0) input.append('\n');
            input.append(line);
        }

        String s = input.toString();

        List<Integer> list1Nums = extractSectionNumbers(s, "list1:");
        int start = extractSingleValue(s, "start:");
        int end = extractSingleValue(s, "end:");
        List<Integer> list2Nums = extractSectionNumbers(s, "list2:");

        ListNode list1 = buildList(list1Nums);
        ListNode list2 = buildList(list2Nums);

        Solution sol = new Solution();
        ListNode result = sol.mergeInBetween(list1, start, end, list2);

        ListNode temp = result;
        while (temp != null) {
            System.out.print(temp.val);
            if (temp.next != null) System.out.print(" ");
            temp = temp.next;
        }
    }
}

