void extractSectionNumbers(const char* s, const char* key, int nums[], int* count) {
    *count = 0;
    char* pos = strstr((char*)s, key);
    if (!pos) return;

    pos += strlen(key);

    while (*pos) {
        while (*pos && !isdigit((unsigned char)*pos) && *pos != '-') {
            if (strncmp(pos, "start", 5) == 0 || strncmp(pos, "end", 3) == 0 || strncmp(pos, "list2", 5) == 0)
                return;
            pos++;
        }

        if (!*pos) break;

        if (isdigit((unsigned char)*pos) || (*pos == '-' && isdigit((unsigned char)*(pos + 1)))) {
            nums[(*count)++] = (int)strtol(pos, &pos, 10);
        }
    }
}

int extractSingleValue(const char* s, const char* key) {
    char* pos = strstr((char*)s, key);
    if (!pos) return 0;
    pos += strlen(key);

    while (*pos && !isdigit((unsigned char)*pos) && *pos != '-') pos++;
    return (int)strtol(pos, NULL, 10);
}

