                    while (i < n && Character.isDigit(input.charAt(i))) {
                        val = val * 10 + (input.charAt(i) - '0');
                        i++;
                    }

                    ops.add(new Operation(op, sign * val));
                }
            } else {
                i++;
            }
        }

