struct PrefixNode {
    int sum;
    struct ListNode* node;
};

struct ListNode* removeZeroSumSublists(struct ListNode* head) {
    struct ListNode* dummy = createNode(0);
    dummy->next = head;

    struct PrefixNode seen[2000];
    int seenCount = 0;

    int prefixSum = 0;
    struct ListNode* curr = dummy;

    while (curr != NULL) {
        prefixSum += curr->val;

        int found = -1;
        for (int i = 0; i < seenCount; i++) {
            if (seen[i].sum == prefixSum) {
                found = i;
                break;
            }
        }

        if (found == -1) {
            seen[seenCount].sum = prefixSum;
            seen[seenCount].node = curr;
            seenCount++;
        } else {
            seen[found].node = curr;
        }

        curr = curr->next;
    }

    prefixSum = 0;
    curr = dummy;

    while (curr != NULL) {
        prefixSum += curr->val;

        for (int i = 0; i < seenCount; i++) {
            if (seen[i].sum == prefixSum) {
                curr->next = seen[i].node->next;
                break;
            }
        }

        curr = curr->next;
    }

    struct ListNode* result = dummy->next;
    free(dummy);
