class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {

        ListNode* dummy = new ListNode(0);
        dummy->next = head;

        unordered_map<int, ListNode*> seen;

        int prefixSum = 0;
        ListNode* curr = dummy;

        while (curr) {
            prefixSum += curr->val;
            seen[prefixSum] = curr;
            curr = curr->next;
        }

        prefixSum = 0;
        curr = dummy;

        while (curr) {
            prefixSum += curr->val;
            curr->next = seen[prefixSum]->next;
            curr = curr->next;
        }

        return dummy->next;
    }
};

