    ListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

public class Solution {

    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        ListNode a = headA;
        ListNode b = headB;

        while (a != b) {
            a = (a == null) ? headB : a.next;
            b = (b == null) ? headA : b.next;
        }

        return a;
    }

    static ListNode buildList(List<Integer> arr) {
        if (arr.isEmpty()) return null;

        ListNode head = new ListNode(arr.get(0));
        ListNode tail = head;

        for (int i = 1; i < arr.size(); i++) {
            tail.next = new ListNode(arr.get(i));
            tail = tail.next;
        }

        return head;
    }

    static ListNode getTail(ListNode head) {
        if (head == null) return null;
        while (head.next != null) head = head.next;
        return head;
    }

    static List<Integer> extractNumbers(String s) {
        List<Integer> nums = new ArrayList<>();
        Matcher m = Pattern.compile("-?\\d+").matcher(s);

        while (m.find()) {
            nums.add(Integer.parseInt(m.group()));
        }

        return nums;
    }

    static List<Integer> extractList(String input, String key) {
        int start = input.indexOf(key);
        if (start == -1) return new ArrayList<>();

        int lb = input.indexOf('[', start);
        int rb = input.indexOf(']', lb);
        if (lb == -1 || rb == -1) return new ArrayList<>();

        String part = input.substring(lb, rb + 1);
        return extractNumbers(part);
    }

    static int extractValue(String input, String key) {
        int start = input.indexOf(key);
        if (start == -1) return 0;

        int eq = input.indexOf('=', start);
        if (eq == -1) return 0;

        String part = input.substring(eq + 1);
        List<Integer> nums = extractNumbers(part);
        return nums.isEmpty() ? 0 : nums.get(0);
    }

