        Scanner sc = new Scanner(System.in);
        StringBuilder inputBuilder = new StringBuilder();

        while (sc.hasNextLine()) {
            inputBuilder.append(sc.nextLine()).append(" ");
        }

        String input = inputBuilder.toString();

        List<Integer> listA = extractList(input, "listA");
        List<Integer> listB = extractList(input, "listB");

        int intersectVal = extractValue(input, "intersectVal");
        int skipA = extractValue(input, "skipA");
        int skipB = extractValue(input, "skipB");

        ListNode headA;
        ListNode headB;

        if (intersectVal == 0) {
            headA = buildList(listA);
            headB = buildList(listB);
        } else {
            List<Integer> common = new ArrayList<>();
            for (int i = skipA; i < listA.size(); i++) {
                common.add(listA.get(i));
            }

            ListNode commonHead = buildList(common);

            headA = buildList(listA.subList(0, skipA));
            headB = buildList(listB.subList(0, skipB));

            if (headA != null) {
                getTail(headA).next = commonHead;
            } else {
                headA = commonHead;
            }

            if (headB != null) {
                getTail(headB).next = commonHead;
            } else {
                headB = commonHead;
            }
        }

        Solution sol = new Solution();
        ListNode ans = sol.getIntersectionNode(headA, headB);

        if (ans != null) {
            System.out.print("Node with value " + ans.val);
        } else {
            System.out.print("null");
        }
    }
}

