struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    vector<int> nodesInCycle(ListNode* head) {

        unordered_set<ListNode*> visited;
        unordered_set<int> cycleValueNodes;
        vector<int> result;

        ListNode* current = head;

        while (current) {

            if (visited.count(current)) {

                ListNode* temp = current;

                do {
                    if (!cycleValueNodes.count(temp->val)) {
                        result.push_back(temp->val);
                        cycleValueNodes.insert(temp->val);
                    }
                    temp = temp->next;
                } while (temp != current);

                break;
            }

            visited.insert(current);
            current = current->next;
        }

        return result;
    }
};

vector<int> extractNumbers(string s) {

    vector<int> nums;
    int i = 0;

    while (i < s.size()) {

        if (isdigit(s[i]) || (s[i]=='-' && i+1<s.size() && isdigit(s[i+1]))) {

            int sign = 1;

            if (s[i]=='-') {
                sign = -1;
                i++;
            }

            int num = 0;

            while (i < s.size() && isdigit(s[i])) {
                num = num*10 + (s[i]-'0');
                i++;
            }

            nums.push_back(sign*num);
        }
        else i++;
    }

    return nums;
}

ListNode* buildList(vector<int> arr) {

    if (arr.empty()) return nullptr;

    ListNode* head = new ListNode(arr[0]);
    ListNode* temp = head;

    for (int i = 1; i < arr.size(); i++) {
        temp->next = new ListNode(arr[i]);
        temp = temp->next;
    }

    return head;
}

void createCycle(ListNode* head, int pos) {

    if (pos < 0 || !head) return;

    ListNode* tail = head;
    ListNode* cycleNode = nullptr;
    int index = 0;

    while (tail->next) {

        if (index == pos)
            cycleNode = tail;

        tail = tail->next;
        index++;
    }

    if (index == pos)
        cycleNode = tail;

    if (cycleNode)
        tail->next = cycleNode;
}

int main() {

    string input, line;

    while (getline(cin,line)) {
        if (!input.empty()) input += " ";
        input += line;
    }

    vector<int> nums = extractNumbers(input);

    int pos = nums.back();
    nums.pop_back();

    ListNode* head = buildList(nums);

    createCycle(head,pos);

    Solution sol;

    vector<int> ans = sol.nodesInCycle(head);

    cout << "[";

    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i];
        if (i < ans.size()-1) cout << ",";
    }

    cout << "]";

    return 0;
}

