public class Solution {

    public static ListNode buildList(List<Integer> nums) {
        if (nums.size() == 0) return null;

        ListNode head = new ListNode(nums.get(0));
        ListNode curr = head;

        for (int i = 1; i < nums.size(); i++) {
            curr.next = new ListNode(nums.get(i));
            curr = curr.next;
        }

        return head;
    }

    public static List<Integer> printReverse(ListNode head) {

        Stack<Integer> stack = new Stack<>();

        while (head != null) {
            stack.push(head.val);
            head = head.next;
        }

        List<Integer> result = new ArrayList<>();

        while (!stack.isEmpty()) {
            result.add(stack.pop());
        }

        return result;
    }

    public static List<Integer> parseInput(String s) {

        List<Integer> nums = new ArrayList<>();
        String num = "";

        for (char c : s.toCharArray()) {

            if (Character.isDigit(c) || c == '-') {
                num += c;
            } 
            else {
                if (!num.isEmpty()) {
                    nums.add(Integer.parseInt(num));
                    num = "";
                }
            }
        }

        if (!num.isEmpty())
            nums.add(Integer.parseInt(num));

        return nums;
    }

    public static void printList(List<Integer> list) {

        System.out.print("[");

        for (int i = 0; i < list.size(); i++) {
            System.out.print(list.get(i));
            if (i != list.size() - 1)
                System.out.print(",");
        }

        System.out.print("]");
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();

        List<Integer> nums = parseInput(input);

        ListNode head = buildList(nums);

        List<Integer> result = printReverse(head);

        printList(result);
    }
}

