        ListNode first = head;
        ListNode last = head;

        for(int i = 1; i < k; i++)
            first = first.next;

        ListNode temp = first;

        while(temp.next != null) {
            temp = temp.next;
            last = last.next;
        }

        int t = first.val;
        first.val = last.val;
        last.val = t;

        return head;
    }

