class ListNode {
    int val;
    ListNode next;
    ListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

public class Solution {

    static ListNode buildList(List<Integer> arr) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int x : arr) {
            tail.next = new ListNode(x);
            tail = tail.next;
        }
        return dummy.next;
    }

    static ListNode mergeTwoLists(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (l1 != null && l2 != null) {
            if (l1.val < l2.val) {
                tail.next = l1;
                l1 = l1.next;
            } else {
                tail.next = l2;
                l2 = l2.next;
            }
            tail = tail.next;
        }

        tail.next = (l1 != null) ? l1 : l2;
        return dummy.next;
    }

    static List<Integer> toArray(ListNode head) {
        List<Integer> res = new ArrayList<>();
        while (head != null) {
            res.add(head.val);
            head = head.next;
        }
        return res;
    }

    static List<Integer> parseList(String s) {
        List<Integer> res = new ArrayList<>();
        Matcher m = Pattern.compile("-?\\d+").matcher(s);
        while (m.find()) {
            res.add(Integer.parseInt(m.group()));
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();
        while (sc.hasNextLine()) {
            if (sb.length() > 0) sb.append("\n");
            sb.append(sc.nextLine());
        }
        String data = sb.toString().trim();

        List<Integer> list1 = new ArrayList<>();
        List<Integer> list2 = new ArrayList<>();

        Matcher bracketMatcher = Pattern.compile("\\[[^\\]]*\\]").matcher(data);
        List<String> bracketParts = new ArrayList<>();
        while (bracketMatcher.find()) {
            bracketParts.add(bracketMatcher.group());
        }

        if (bracketParts.size() >= 2) {
            list1 = parseList(bracketParts.get(0));
            list2 = parseList(bracketParts.get(1));
        } else if (data.contains("|")) {
            String[] parts = data.split("\\|", 2);
            list1 = parseList(parts[0]);
            list2 = parseList(parts[1]);
        } else {
            String[] lines = data.split("\\R");
            List<String> nonEmpty = new ArrayList<>();
            for (String line : lines) {
                if (!line.trim().isEmpty()) nonEmpty.add(line.trim());
            }
            if (nonEmpty.size() >= 2) {
                list1 = parseList(nonEmpty.get(0));
                list2 = parseList(nonEmpty.get(1));
            }
        }

        ListNode l1 = buildList(list1);
        ListNode l2 = buildList(list2);

        ListNode merged = mergeTwoLists(l1, l2);
        List<Integer> ans = toArray(merged);

        System.out.print("[");
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) System.out.print(",");
            System.out.print(ans.get(i));
        }
        System.out.print("]");
    }
}

