import sys


class Node:
    def __init__(self, x: int, next=None, random=None):
        self.val = int(x)
        self.next = next
        self.random = random


class Solution:
    def copyRandomList(self, head):
        if not head:
            return None

        old_to_new = {}
        curr = head

        while curr:
            old_to_new[curr] = Node(curr.val)
            curr = curr.next

        curr = head
        while curr:
            old_to_new[curr].next = old_to_new.get(curr.next)
            old_to_new[curr].random = old_to_new.get(curr.random)
            curr = curr.next

        return old_to_new[head]


def parse_input(text):
    l = text.find('[')
    r = text.rfind(']')
    if l == -1 or r == -1 or l > r:
        return []

    s = text[l:r + 1].strip()
    if s == "[]":
        return []

    arr = []
    i = 0
    n = len(s)

    while i < n:
        if s[i] == '[' and i + 1 < n and s[i + 1] != '[':
            j = i + 1
            while j < n and s[j] != ']':
                j += 1
            if j >= n:
                break

            inside = s[i + 1:j]
            if ',' in inside:
                a, b = inside.split(',', 1)
                a = a.strip()
                b = b.strip()

                val = int(a)
                rnd = -1 if b == "null" else int(b)
                arr.append((val, rnd))

            i = j
        i += 1

    return arr


def build_list(arr):
    if not arr:
        return None, []

    nodes = [Node(val) for val, _ in arr]

    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]

    for i, (_, rnd) in enumerate(arr):
        if rnd != -1:
            nodes[i].random = nodes[rnd]

    return nodes[0], nodes


def serialize(head):
    if not head:
        return "[]"

    nodes = []
    index = {}
    curr = head

    while curr:
        index[curr] = len(nodes)
        nodes.append(curr)
        curr = curr.next

    parts = []
    for node in nodes:
        if node.random is None:
            parts.append(f"[{node.val},null]")
        else:
            parts.append(f"[{node.val},{index[node.random]}]")

    return "[" + ",".join(parts) + "]"


