import java.io.*;
import java.util.*;

class Node {
    int val;
    Node next;
    Node random;

    Node(int val) {
        this.val = val;
        this.next = null;
        this.random = null;
    }
}

public class Solution {

    public Node copyRandomList(Node head) {
        if (head == null) return null;

        Map<Node, Node> map = new HashMap<>();
        Node curr = head;

        while (curr != null) {
            map.put(curr, new Node(curr.val));
            curr = curr.next;
        }

        curr = head;
        while (curr != null) {
            map.get(curr).next = map.get(curr.next);
            map.get(curr).random = map.get(curr.random);
            curr = curr.next;
        }

        return map.get(head);
    }

    static class Pair {
        int val;
        int randomIndex;

        Pair(int val, int randomIndex) {
            this.val = val;
            this.randomIndex = randomIndex;
        }
    }

    static String trim(String s) {
        return s == null ? "" : s.trim();
    }

    static List<Pair> parseInput(String input) {
        List<Pair> arr = new ArrayList<>();

        int l = input.indexOf('[');
        int r = input.lastIndexOf(']');
        if (l == -1 || r == -1 || l > r) return arr;

        String s = input.substring(l, r + 1);
        if (s.equals("[]")) return arr;

        for (int i = 0; i + 1 < s.length(); i++) {
            if (s.charAt(i) == '[' && s.charAt(i + 1) != '[') {
                int j = i + 1;
                while (j < s.length() && s.charAt(j) != ']') j++;
                if (j >= s.length()) break;

                String inside = s.substring(i + 1, j);
                int comma = inside.indexOf(',');
                if (comma == -1) {
                    i = j;
                    continue;
                }

                String a = trim(inside.substring(0, comma));
                String b = trim(inside.substring(comma + 1));

                int val = Integer.parseInt(a);
                int rnd = b.equals("null") ? -1 : Integer.parseInt(b);

                arr.add(new Pair(val, rnd));
                i = j;
            }
        }

        return arr;
    }

    static Node buildList(List<Pair> arr, List<Node> nodes) {
        if (arr.isEmpty()) return null;

        for (Pair p : arr) {
            nodes.add(new Node(p.val));
        }

        for (int i = 0; i + 1 < nodes.size(); i++) {
            nodes.get(i).next = nodes.get(i + 1);
        }

        for (int i = 0; i < arr.size(); i++) {
            int r = arr.get(i).randomIndex;
            if (r != -1) {
                nodes.get(i).random = nodes.get(r);
            }
        }

        return nodes.get(0);
    }

    static void printList(Node head) {
        Map<Node, Integer> idx = new HashMap<>();
        List<Node> nodes = new ArrayList<>();

        Node curr = head;
        int i = 0;
        while (curr != null) {
            idx.put(curr, i++);
            nodes.add(curr);
            curr = curr.next;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("[");

        for (int j = 0; j < nodes.size(); j++) {
            Node node = nodes.get(j);
            sb.append("[").append(node.val).append(",");

            if (node.random == null) sb.append("null");
            else sb.append(idx.get(node.random));

            sb.append("]");
            if (j + 1 < nodes.size()) sb.append(",");
        }

        sb.append("]");
        System.out.print(sb.toString());
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            if (input.length() > 0) input.append(" ");
            input.append(line);
        }

        List<Pair> arr = parseInput(input.toString());
        if (arr.isEmpty()) {
            System.out.print("[]");
            return;
        }

        List<Node> nodes = new ArrayList<>();
        Node head = buildList(arr, nodes);

        Solution sol = new Solution();
        Node copied = sol.copyRandomList(head);

        printList(copied);
    }
}

