class Node:
    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None
        self.child = None


class Solution:
    def flatten(self, head):
        if not head:
            return None

        stack = [head]
        prev = None

        while stack:
            node = stack.pop()

            if prev:
                prev.next = node
                node.prev = prev

            if node.next:
                stack.append(node.next)

            if node.child:
                stack.append(node.child)
                node.child = None

            prev = node

        return head


def parse_tokens(text):
    l = text.find('[')
    r = text.rfind(']')
    if l == -1 or r == -1 or l > r:
        return []

    inside = text[l + 1:r].strip()
    if not inside:
        return []

    return [x.strip() for x in inside.split(',')]


def build_linear(vals):
    head = None
    tail = None
    nodes = []

    for s in vals:
        if s == "null" or s == "":
            continue

        node = Node(int(s))
        nodes.append(node)

        if head is None:
            head = tail = node
        else:
            tail.next = node
            node.prev = tail
            tail = node

    return head, nodes


def build_multilevel(tokens):
    if not tokens:
        return None
    if len(tokens) == 1 and tokens[0] == "null":
        return None

    first_null = -1
    for i, tok in enumerate(tokens):
        if tok == "null":
            first_null = i
            break

    if first_null == -1:
        head, _ = build_linear(tokens)
        return head

    head, prev_level = build_linear(tokens[:first_null])

    start = first_null
    while start < len(tokens):
        parent_index = -1

        while start < len(tokens) and tokens[start] == "null":
            parent_index += 1
            start += 1

        if start >= len(tokens):
            break
        if parent_index < 0 or parent_index >= len(prev_level):
            break

        end = start
        while end < len(tokens) and tokens[end] != "null":
            end += 1

        child_head, next_level = build_linear(tokens[start:end])
        prev_level[parent_index].child = child_head

        prev_level = next_level
        start = end

    return head


def print_list(head):
    vals = []
    curr = head
    while curr:
        vals.append(str(curr.val))
        curr = curr.next
    print("[" + ",".join(vals) + "]", end="")


