import java.io.*;
import java.util.*;

class Node {
    int val;
    Node prev;
    Node next;
    Node child;

    Node(int val) {
        this.val = val;
    }
}

public class Solution {

    public Node flatten(Node head) {
        if (head == null) return null;

        Deque<Node> stack = new ArrayDeque<>();
        stack.push(head);
        Node prev = null;

        while (!stack.isEmpty()) {
            Node node = stack.pop();

            if (prev != null) {
                prev.next = node;
                node.prev = prev;
            }

            if (node.next != null) stack.push(node.next);

            if (node.child != null) {
                stack.push(node.child);
                node.child = null;
            }

            prev = node;
        }

        return head;
    }

    static String trim(String s) {
        return s == null ? "" : s.trim();
    }

    static List<String> parseTokens(String input) {
        int l = input.indexOf('[');
        int r = input.lastIndexOf(']');
        List<String> tokens = new ArrayList<>();

        if (l == -1 || r == -1 || l > r) return tokens;

        String inside = input.substring(l + 1, r);
        if (inside.trim().isEmpty()) return tokens;

        String[] parts = inside.split(",");
        for (String part : parts) {
            tokens.add(part.trim());
        }

        return tokens;
    }

    static Node buildLinear(List<String> vals, List<Node> outNodes) {
        Node head = null, tail = null;

        for (String s : vals) {
            if (s.equals("null") || s.isEmpty()) continue;

            Node node = new Node(Integer.parseInt(s));
            outNodes.add(node);

            if (head == null) {
                head = tail = node;
            } else {
                tail.next = node;
                node.prev = tail;
                tail = node;
            }
        }

        return head;
    }

    static Node buildMultilevel(List<String> tokens) {
        if (tokens.isEmpty()) return null;
        if (tokens.size() == 1 && tokens.get(0).equals("null")) return null;

        int firstNull = -1;
        for (int i = 0; i < tokens.size(); i++) {
            if (tokens.get(i).equals("null")) {
                firstNull = i;
                break;
            }
        }

        if (firstNull == -1) {
            List<Node> dummy = new ArrayList<>();
            return buildLinear(tokens, dummy);
        }

        List<Node> prevLevel = new ArrayList<>();
        Node head = buildLinear(tokens.subList(0, firstNull), prevLevel);

        int start = firstNull;

        while (start < tokens.size()) {
            int parentIndex = -1;

            while (start < tokens.size() && tokens.get(start).equals("null")) {
                parentIndex++;
                start++;
            }

            if (start >= tokens.size()) break;
            if (parentIndex < 0 || parentIndex >= prevLevel.size()) break;

            int end = start;
            while (end < tokens.size() && !tokens.get(end).equals("null")) {
                end++;
            }

            List<Node> nextLevel = new ArrayList<>();
            Node childHead = buildLinear(tokens.subList(start, end), nextLevel);
            prevLevel.get(parentIndex).child = childHead;

            prevLevel = nextLevel;
            start = end;
        }

        return head;
    }

    static void printList(Node head) {
        StringBuilder sb = new StringBuilder();
        sb.append("[");

        Node curr = head;
        while (curr != null) {
            sb.append(curr.val);
            if (curr.next != null) sb.append(",");
            curr = curr.next;
        }

        sb.append("]");
        System.out.print(sb.toString());
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            if (input.length() > 0) input.append(" ");
            input.append(line);
        }

        List<String> tokens = parseTokens(input.toString());
        Node head = buildMultilevel(tokens);

        Solution sol = new Solution();
        head = sol.flatten(head);

        printList(head);
    }
}

