};

struct Node* newNode(int val) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->val = val;
    node->next = NULL;
    node->prev = NULL;
    node->child = NULL;
    return node;
}

struct Node* flatten(struct Node* head) {
    if (!head) return NULL;

    struct Node* stack[2000];
    int top = -1;
    stack[++top] = head;

    struct Node* prev = NULL;

    while (top >= 0) {
        struct Node* curr = stack[top--];

        if (prev) {
            prev->next = curr;
            curr->prev = prev;
        }

        if (curr->next)
            stack[++top] = curr->next;

        if (curr->child) {
            stack[++top] = curr->child;
            curr->child = NULL;
        }

        prev = curr;
    }

    return head;
}

void trim(char* s) {
    int n = (int)strlen(s);
    int i = 0, j = n - 1;

    while (i < n && isspace((unsigned char)s[i])) i++;
    while (j >= i && isspace((unsigned char)s[j])) j--;

    if (i > 0)
        memmove(s, s + i, j - i + 2);

    s[j - i + 1] = '\0';
}

int parseTokens(char* input, char tokens[][20]) {
    char* l = strchr(input, '[');
    char* r = strrchr(input, ']');

    if (!l || !r || l > r) return 0;

    *r = '\0';
    l++;

    int count = 0;
    char* tok = strtok(l, ",");

    while (tok) {
        trim(tok);
        strcpy(tokens[count++], tok);
        tok = strtok(NULL, ",");
    }

    return count;
}

struct Node* buildLinear(char vals[][20], int start, int end, struct Node** outNodes, int* outCount) {
    struct Node* head = NULL;
    struct Node* tail = NULL;
    *outCount = 0;

    for (int i = start; i < end; i++) {
        if (strcmp(vals[i], "null") == 0 || vals[i][0] == '\0')
            continue;

        struct Node* node = newNode(atoi(vals[i]));
        outNodes[(*outCount)++] = node;

        if (!head) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    return head;
}

struct Node* buildMultilevel(char tokens[][20], int n) {
    if (n == 0) return NULL;
    if (n == 1 && strcmp(tokens[0], "null") == 0) return NULL;

    int firstNull = -1;
    for (int i = 0; i < n; i++) {
        if (strcmp(tokens[i], "null") == 0) {
            firstNull = i;
            break;
        }
    }

    if (firstNull == -1) {
        struct Node* dummy[1000];
        int cnt;
        return buildLinear(tokens, 0, n, dummy, &cnt);
    }

    struct Node* prevLevel[1000];
    int prevCount = 0;
    struct Node* head = buildLinear(tokens, 0, firstNull, prevLevel, &prevCount);

    int start = firstNull;
    while (start < n) {
        int parentIndex = -1;

        while (start < n && strcmp(tokens[start], "null") == 0) {
            parentIndex++;
            start++;
        }

        if (start >= n)
            break;

        if (parentIndex < 0 || parentIndex >= prevCount)
            break;

        int end = start;
        while (end < n && strcmp(tokens[end], "null") != 0)
            end++;

        struct Node* nextLevel[1000];
        int nextCount = 0;

        struct Node* childHead = buildLinear(tokens, start, end, nextLevel, &nextCount);
        prevLevel[parentIndex]->child = childHead;

        for (int i = 0; i < nextCount; i++)
            prevLevel[i] = nextLevel[i];
        prevCount = nextCount;

        start = end;
    }

    return head;
}

void printList(struct Node* head) {
    printf("[");
