Node* buildLevel(const vector<string>& tokens, int& idx) {
    if (idx >= (int)tokens.size() || tokens[idx] == "null")
        return NULL;

    Node* head = NULL;
    Node* tail = NULL;
    vector<Node*> nodes;

    while (idx < (int)tokens.size() && tokens[idx] != "null") {
        Node* node = new Node(stoi(tokens[idx]));
        nodes.push_back(node);

        if (!head) {
            head = tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
        idx++;
    }

    if (idx < (int)tokens.size() && tokens[idx] == "null")
        idx++;

    for (Node* node : nodes) {
        if (idx >= (int)tokens.size())
            break;

        if (tokens[idx] == "null") {
            idx++;
        } else {
            node->child = buildLevel(tokens, idx);
        }
    }

    return head;
}

