import sys

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.data = []  # [key, value]

    def find_key(self, key):
        for i in range(len(self.data)):
            if self.data[i][0] == key:
                return i
        return -1

    def move_to_front(self, idx):
        if idx <= 0 or idx >= len(self.data):
            return
        item = self.data.pop(idx)
        self.data.insert(0, item)

    def get(self, key):
        idx = self.find_key(key)
        if idx == -1:
            return -1

        value = self.data[idx][1]
        self.move_to_front(idx)
        return value

    def put(self, key, value):
        if self.cap <= 0:
            return

        idx = self.find_key(key)

        if idx != -1:
            self.data[idx][1] = value
            self.move_to_front(idx)
            return

        if len(self.data) == self.cap:
            self.data.pop(0)

        self.data.insert(0, [key, value])


def parse_capacity(s):
