    while idx < len(s) and not (s[idx].isdigit() or s[idx] == '-'):
        idx += 1

    num = ""
    if idx < len(s) and s[idx] == '-':
        num += s[idx]
        idx += 1

    while idx < len(s) and s[idx].isdigit():
        num += s[idx]
        idx += 1

    return int(num) if num and num != "-" else 0


