#define MAX_ITEMS 1000
#define MAX_OUTPUT 2000
#define MAX_INPUT 10000

typedef struct {
    int key;
    int value;
} Pair;

typedef struct {
    int cap;
    Pair arr[MAX_ITEMS];
    int size;
} LRUCache;

void initCache(LRUCache* cache, int capacity) {
    cache->cap = capacity;
    cache->size = 0;
}

int findKey(LRUCache* cache, int key) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->arr[i].key == key) return i;
    }
    return -1;
}

void moveToFront(LRUCache* cache, int idx) {
    if (idx <= 0 || idx >= cache->size) return;

    Pair temp = cache->arr[idx];
    for (int i = idx; i > 0; i--) {
        cache->arr[i] = cache->arr[i - 1];
    }
    cache->arr[0] = temp;
}

int get(LRUCache* cache, int key) {
    int idx = findKey(cache, key);
    if (idx == -1) return -1;

    int value = cache->arr[idx].value;
    moveToFront(cache, idx);
    return value;
}

void put(LRUCache* cache, int key, int value) {
    if (cache->cap <= 0) return;

    int idx = findKey(cache, key);

    if (idx != -1) {
        cache->arr[idx].value = value;
        moveToFront(cache, idx);
        return;
    }

    if (cache->size == cache->cap) {
        for (int i = 0; i < cache->size - 1; i++) {
            cache->arr[i] = cache->arr[i + 1];
        }
        cache->size--;
    }

    for (int i = cache->size; i > 0; i--) {
        cache->arr[i] = cache->arr[i - 1];
    }

    cache->arr[0].key = key;
    cache->arr[0].value = value;
    cache->size++;
}

int parseCapacity(const char* s) {
    const char* p = strstr(s, "capacity");
    if (p == NULL) return 0;

    while (*p && *p != '=') p++;
    if (*p == '=') p++;

    while (*p && !isdigit((unsigned char)*p) && *p != '-') p++;

    return atoi(p);
}

int main() {
    char input[MAX_INPUT] = "";
    char line[1024];

    while (fgets(line, sizeof(line), stdin)) {
        if (strlen(input) + strlen(line) < MAX_INPUT - 1) {
            strcat(input, line);
        }
    }

    int capacity = parseCapacity(input);
    LRUCache cache;
    initCache(&cache, capacity);

    char output[MAX_OUTPUT][32];
    int outCount = 0;

    for (int i = 0; input[i] != '\0'; i++) {
        if (strncmp(&input[i], "put", 3) == 0) {
            char* p1 = strchr(&input[i], ',');
            if (!p1) break;
            int key = atoi(p1 + 1);

            char* p2 = strchr(p1 + 1, ',');
            if (!p2) break;
            int value = atoi(p2 + 1);

            put(&cache, key, value);
            strcpy(output[outCount++], "null");
        }
        else if (strncmp(&input[i], "get", 3) == 0) {
            char* p1 = strchr(&input[i], ',');
            if (!p1) break;
            int key = atoi(p1 + 1);

            sprintf(output[outCount++], "%d", get(&cache, key));
        }
    }

    printf("[");
    for (int i = 0; i < outCount; i++) {
        if (i > 0) printf(",");
        printf("%s", output[i]);
    }
    printf("]");

    return 0;
}

