import sys

class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.timer = 0
        self.data = []  # each item: [key, value, freq, time]

    def find(self, key):
        for i in range(len(self.data)):
            if self.data[i][0] == key:
                return i
        return -1

    def get(self, key):
        idx = self.find(key)
        if idx == -1:
            return -1

        self.data[idx][2] += 1
        self.timer += 1
        self.data[idx][3] = self.timer
        return self.data[idx][1]

    def put(self, key, value):
        if self.cap <= 0:
            return

        idx = self.find(key)

        if idx != -1:
            self.data[idx][1] = value
            self.data[idx][2] += 1
            self.timer += 1
            self.data[idx][3] = self.timer
            return

        if len(self.data) >= self.cap:
            remove = 0
            for i in range(1, len(self.data)):
                if self.data[i][2] < self.data[remove][2] or (
                    self.data[i][2] == self.data[remove][2] and
                    self.data[i][3] > self.data[remove][3]
                ):
                    remove = i
            self.data.pop(remove)

        self.timer += 1
        self.data.append([key, value, 1, self.timer])


def parse_capacity(s):
    idx = s.find("capacity")
    if idx == -1:
        return 0

    idx = s.find("=", idx)
    if idx == -1:
        return 0
    idx += 1

    while idx < len(s) and not (s[idx].isdigit() or s[idx] == '-'):
        idx += 1

    num = ""
    if idx < len(s) and s[idx] == '-':
        num += s[idx]
        idx += 1

    while idx < len(s) and s[idx].isdigit():
        num += s[idx]
        idx += 1

    return int(num) if num else 0


