typedef struct {
    Node arr[MAX_KEYS];
    int size;
    int cap;
    int timer;
} LFUCache;

void init(LFUCache* cache, int capacity) {
    cache->size = 0;
    cache->cap = capacity;
    cache->timer = 0;
}

int findKey(LFUCache* cache, int key) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->arr[i].key == key) return i;
    }
    return -1;
}

int get(LFUCache* cache, int key) {
    int idx = findKey(cache, key);
    if (idx == -1) return -1;

    cache->arr[idx].freq++;
    cache->arr[idx].time = ++cache->timer;
    return cache->arr[idx].value;
}

void put(LFUCache* cache, int key, int value) {
    if (cache->cap <= 0) return;

    int idx = findKey(cache, key);

    if (idx != -1) {
        cache->arr[idx].value = value;
        cache->arr[idx].freq++;
        cache->arr[idx].time = ++cache->timer;
        return;
    }

    if (cache->size >= cache->cap) {
        int remove = 0;

        for (int i = 1; i < cache->size; i++) {
            if (cache->arr[i].freq < cache->arr[remove].freq ||
               (cache->arr[i].freq == cache->arr[remove].freq &&
                cache->arr[i].time > cache->arr[remove].time)) {
                remove = i;
            }
        }

        for (int i = remove; i < cache->size - 1; i++) {
            cache->arr[i] = cache->arr[i + 1];
        }

        cache->size--;
    }

    cache->arr[cache->size].key = key;
    cache->arr[cache->size].value = value;
    cache->arr[cache->size].freq = 1;
    cache->arr[cache->size].time = ++cache->timer;
    cache->size++;
}

