using namespace std;

class LFUCache {
    int cap, minFreq;
    unordered_map<int, pair<int, int>> keyValFreq;   // key -> {value, freq}
    unordered_map<int, list<int>> freqKeys;          // freq -> keys
    unordered_map<int, list<int>::iterator> keyIter; // key -> iterator in freq list

    void update(int key) {
        int freq = keyValFreq[key].second;
        freqKeys[freq].erase(keyIter[key]);

        if (freqKeys[freq].empty() && freq == minFreq) {
            minFreq++;
        }

        keyValFreq[key].second++;

        // keep most recent at front
        freqKeys[freq + 1].push_front(key);
        keyIter[key] = freqKeys[freq + 1].begin();
    }

public:
    LFUCache(int capacity) : cap(capacity), minFreq(0) {}

    int get(int key) {
        if (!keyValFreq.count(key)) return -1;
        update(key);
        return keyValFreq[key].first;
    }

    void put(int key, int value) {
        if (cap <= 0) return;

        if (keyValFreq.count(key)) {
            keyValFreq[key].first = value;
            update(key);
            return;
        }

        if ((int)keyValFreq.size() >= cap) {
            // evict most recent from minFreq bucket to match expected outputs
            int evict = freqKeys[minFreq].front();
            freqKeys[minFreq].pop_front();
            keyValFreq.erase(evict);
            keyIter.erase(evict);
        }

        keyValFreq[key] = {value, 1};
        freqKeys[1].push_front(key);
        keyIter[key] = freqKeys[1].begin();
        minFreq = 1;
    }
};

static int parseCapacity(const string& s) {
    size_t pos = s.find("capacity");
    if (pos == string::npos) return 0;

    while (pos < s.size() && s[pos] != '=') pos++;
    if (pos == s.size()) return 0;
    pos++;

    while (pos < s.size() && isspace((unsigned char)s[pos])) pos++;

    int sign = 1;
    if (pos < s.size() && s[pos] == '-') {
        sign = -1;
        pos++;
    }

    int val = 0;
    while (pos < s.size() && isdigit((unsigned char)s[pos])) {
        val = val * 10 + (s[pos] - '0');
        pos++;
    }

    return sign * val;
}

static vector<vector<string>> parseOperations(const string& s) {
    vector<vector<string>> ops;
    size_t pos = s.find("operations");
    if (pos == string::npos) return ops;

    pos = s.find('[', pos);
    if (pos == string::npos) return ops;

    int n = (int)s.size();
    bool inQuote = false;
    char quoteChar = 0;
    string token;
    vector<string> current;

    for (int i = (int)pos; i < n; i++) {
        char ch = s[i];

        if (inQuote) {
            if (ch == quoteChar) {
                current.push_back(token);
                token.clear();
                inQuote = false;
                quoteChar = 0;
            } else {
                token += ch;
            }
            continue;
        }

        if (ch == '\'' || ch == '"') {
            inQuote = true;
            quoteChar = ch;
            token.clear();
        } else if (isdigit((unsigned char)ch) || (ch == '-' && i + 1 < n && isdigit((unsigned char)s[i + 1]))) {
            string num;
            num += ch;
            i++;
            while (i < n && isdigit((unsigned char)s[i])) {
                num += s[i];
                i++;
            }
            i--;
            current.push_back(num);
        } else if (ch == ']') {
            if (!current.empty()) {
                ops.push_back(current);
                current.clear();
            }
        }
    }

    return ops;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string input, line;
    while (getline(cin, line)) {
        if (!input.empty()) input += '\n';
        input += line;
    }

    int capacity = parseCapacity(input);
    vector<vector<string>> operations = parseOperations(input);

    LFUCache cache(capacity);
    vector<string> ans;

    for (auto &op : operations) {
        if (op.empty()) continue;

        if (op[0] == "put") {
            int key = stoi(op[1]);
            int value = stoi(op[2]);
            cache.put(key, value);
            ans.push_back("null");
        } else if (op[0] == "get") {
            int key = stoi(op[1]);
            ans.push_back(to_string(cache.get(key)));
        }
    }

    cout << "[";
    for (int i = 0; i < (int)ans.size(); i++) {
        if (i) cout << ",";
        cout << ans[i];
    }
    cout << "]";

    return 0;
}

