class AllOne:
    def __init__(self):
        self.data = {}

    def inc(self, key):
        if key in self.data:
            self.data[key] += 1
        else:
            self.data[key] = 1

    def dec(self, key):
        if key not in self.data:
            return
        self.data[key] -= 1
        if self.data[key] == 0:
            del self.data[key]

    def getMaxKey(self):
        if not self.data:
            return ""
        return max(self.data, key=self.data.get)

    def getMinKey(self):
        if not self.data:
            return ""
        return min(self.data, key=self.data.get)


