import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

class AllOne {
    private static class Node {
        int count;
        Set<String> keys;

        Node(int count) {
            this.count = count;
            this.keys = new HashSet<>();
        }
    }

    private final LinkedList<Node> buckets = new LinkedList<>();
    private final Map<String, Node> keyToNode = new HashMap<>();

    public void inc(String key) {
        if (!keyToNode.containsKey(key)) {
            if (buckets.isEmpty() || buckets.getFirst().count != 1) {
                Node node = new Node(1);
                node.keys.add(key);
                buckets.addFirst(node);
                keyToNode.put(key, node);
            } else {
                buckets.getFirst().keys.add(key);
                keyToNode.put(key, buckets.getFirst());
            }
        } else {
            Node cur = keyToNode.get(key);
            int idx = buckets.indexOf(cur);
            Node nextNode = (idx + 1 < buckets.size()) ? buckets.get(idx + 1) : null;

            if (nextNode == null || nextNode.count != cur.count + 1) {
                Node newNode = new Node(cur.count + 1);
                newNode.keys.add(key);
                buckets.add(idx + 1, newNode);
                keyToNode.put(key, newNode);
            } else {
                nextNode.keys.add(key);
                keyToNode.put(key, nextNode);
            }

            cur.keys.remove(key);
            if (cur.keys.isEmpty()) {
                buckets.remove(cur);
            }
        }
    }

    public void dec(String key) {
        if (!keyToNode.containsKey(key)) return;

        Node cur = keyToNode.get(key);
        int idx = buckets.indexOf(cur);

        if (cur.count == 1) {
            keyToNode.remove(key);
        } else {
            Node prevNode = (idx - 1 >= 0) ? buckets.get(idx - 1) : null;

            if (prevNode == null || prevNode.count != cur.count - 1) {
                Node newNode = new Node(cur.count - 1);
                newNode.keys.add(key);
                buckets.add(idx, newNode);
                keyToNode.put(key, newNode);
            } else {
                prevNode.keys.add(key);
                keyToNode.put(key, prevNode);
            }
        }

        cur.keys.remove(key);
        if (cur.keys.isEmpty()) {
            buckets.remove(cur);
        }
    }

    public String getMaxKey() {
        if (buckets.isEmpty()) return "";
        return buckets.getLast().keys.iterator().next();
    }

    public String getMinKey() {
        if (buckets.isEmpty()) return "";
        return buckets.getFirst().keys.iterator().next();
    }
}

public class Solution {
    private static List<String> extractQuotedTokens(String s) {
        List<String> tokens = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        boolean inQuote = false;
        char quoteChar = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (!inQuote) {
                if (ch == '\'' || ch == '"') {
                    inQuote = true;
                    quoteChar = ch;
                    cur.setLength(0);
                }
            } else {
                if (ch == quoteChar) {
                    tokens.add(cur.toString());
                    cur.setLength(0);
                    inQuote = false;
                    quoteChar = 0;
                } else {
                    cur.append(ch);
                }
            }
        }

        return tokens;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            input.append(line).append('\n');
        }

        List<String> tokens = extractQuotedTokens(input.toString());
        AllOne obj = new AllOne();
        List<String> ans = new ArrayList<>();

        for (int i = 0; i < tokens.size();) {
            String op = tokens.get(i++);

            if (op.equals("inc")) {
                if (i < tokens.size()) obj.inc(tokens.get(i++));
                ans.add("null");
            } else if (op.equals("dec")) {
                if (i < tokens.size()) obj.dec(tokens.get(i++));
                ans.add("null");
            } else if (op.equals("getMaxKey")) {
                ans.add("'" + obj.getMaxKey() + "'");
            } else if (op.equals("getMinKey")) {
                ans.add("'" + obj.getMinKey() + "'");
            }
        }

        System.out.print("[");
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) System.out.print(",");
            System.out.print(ans.get(i));
        }
        System.out.print("]");
    }
}

