#define MAX_KEYS 1000
#define MAX_KEY_LEN 256
#define MAX_TOKENS 5000
#define MAX_INPUT 200000

typedef struct {
    char key[MAX_KEY_LEN];
    int count;
} KeyEntry;

typedef struct {
    KeyEntry arr[MAX_KEYS];
    int size;
} AllOne;

void initAllOne(AllOne* obj) {
    obj->size = 0;
}

int findKey(AllOne* obj, const char* key) {
    for (int i = 0; i < obj->size; i++) {
        if (strcmp(obj->arr[i].key, key) == 0) {
            return i;
        }
    }
    return -1;
}

void inc(AllOne* obj, const char* key) {
    int idx = findKey(obj, key);
    if (idx == -1) {
        strcpy(obj->arr[obj->size].key, key);
        obj->arr[obj->size].count = 1;
        obj->size++;
    } else {
        obj->arr[idx].count++;
    }
}

void dec(AllOne* obj, const char* key) {
    int idx = findKey(obj, key);
    if (idx == -1) return;

    obj->arr[idx].count--;

    if (obj->arr[idx].count == 0) {
        for (int i = idx; i < obj->size - 1; i++) {
            obj->arr[i] = obj->arr[i + 1];
        }
        obj->size--;
    }
}

const char* getMaxKey(AllOne* obj) {
    if (obj->size == 0) return "";

    int maxIdx = 0;
    for (int i = 1; i < obj->size; i++) {
        if (obj->arr[i].count > obj->arr[maxIdx].count) {
            maxIdx = i;
        }
    }
    return obj->arr[maxIdx].key;
}

const char* getMinKey(AllOne* obj) {
    if (obj->size == 0) return "";

    int minIdx = 0;
    for (int i = 1; i < obj->size; i++) {
        if (obj->arr[i].count < obj->arr[minIdx].count) {
            minIdx = i;
        }
    }
    return obj->arr[minIdx].key;
}

int extractQuotedTokens(const char* input, char tokens[MAX_TOKENS][MAX_KEY_LEN]) {
    int count = 0;
    int i = 0;

    while (input[i] != '\0') {
        if (input[i] == '\'' || input[i] == '"') {
            char quote = input[i++];
            int j = 0;

            while (input[i] != '\0' && input[i] != quote) {
                if (j < MAX_KEY_LEN - 1) {
                    tokens[count][j++] = input[i];
                }
                i++;
            }

            tokens[count][j] = '\0';
            count++;

            if (input[i] == quote) i++;
        } else {
            i++;
        }
    }

    return count;
}

int main() {
    char input[MAX_INPUT] = "";
    char line[4096];

    while (fgets(line, sizeof(line), stdin)) {
        if (strlen(input) + strlen(line) < MAX_INPUT - 1) {
            strcat(input, line);
        }
    }

    char tokens[MAX_TOKENS][MAX_KEY_LEN];
    int tokenCount = extractQuotedTokens(input, tokens);

    AllOne obj;
    initAllOne(&obj);

    char answers[MAX_TOKENS][MAX_KEY_LEN + 10];
    int ansCount = 0;

    int i = 0;
    while (i < tokenCount) {
        if (strcmp(tokens[i], "inc") == 0) {
            if (i + 1 < tokenCount) {
                inc(&obj, tokens[i + 1]);
                i += 2;
            } else {
                i++;
            }
            strcpy(answers[ansCount++], "null");
        } else if (strcmp(tokens[i], "dec") == 0) {
            if (i + 1 < tokenCount) {
                dec(&obj, tokens[i + 1]);
                i += 2;
            } else {
                i++;
            }
            strcpy(answers[ansCount++], "null");
        } else if (strcmp(tokens[i], "getMaxKey") == 0) {
            snprintf(answers[ansCount], sizeof(answers[ansCount]), "'%s'", getMaxKey(&obj));
            ansCount++;
            i++;
        } else if (strcmp(tokens[i], "getMinKey") == 0) {
            snprintf(answers[ansCount], sizeof(answers[ansCount]), "'%s'", getMinKey(&obj));
            ansCount++;
            i++;
        } else {
            i++;
        }
    }

    printf("[");
    for (i = 0; i < ansCount; i++) {
        if (i > 0) printf(",");
        printf("%s", answers[i]);
    }
    printf("]");

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <list>
#include <vector>
#include <cctype>
using namespace std;

class AllOne {
    struct Node {
        int count;
        unordered_set<string> keys;
    };

    list<Node> buckets;
    unordered_map<string, list<Node>::iterator> pos;

public:
    void inc(const string& key) {
        if (!pos.count(key)) {
            if (buckets.empty() || buckets.front().count != 1) {
                buckets.push_front({1, {key}});
            } else {
                buckets.front().keys.insert(key);
            }
            pos[key] = buckets.begin();
            return;
        }

        auto cur = pos[key];
        auto nxt = next(cur);

        if (nxt == buckets.end() || nxt->count != cur->count + 1) {
            nxt = buckets.insert(nxt, {cur->count + 1, {key}});
        } else {
            nxt->keys.insert(key);
        }

        pos[key] = nxt;
        cur->keys.erase(key);

        if (cur->keys.empty()) {
            buckets.erase(cur);
        }
    }

    void dec(const string& key) {
        if (!pos.count(key)) return;

        auto cur = pos[key];

        if (cur->count == 1) {
            pos.erase(key);
        } else {
            if (cur == buckets.begin() || prev(cur)->count != cur->count - 1) {
                auto newNode = buckets.insert(cur, {cur->count - 1, {key}});
                pos[key] = newNode;
            } else {
                auto prv = prev(cur);
                prv->keys.insert(key);
                pos[key] = prv;
            }
        }

        cur->keys.erase(key);

        if (cur->keys.empty()) {
            buckets.erase(cur);
        }
    }

    string getMaxKey() {
        return buckets.empty() ? "" : *buckets.back().keys.begin();
    }

    string getMinKey() {
        return buckets.empty() ? "" : *buckets.front().keys.begin();
    }
};

static vector<string> extractQuotedTokens(const string& s) {
    vector<string> tokens;
    string cur;
    bool inQuote = false;
    char quoteChar = 0;

    for (char ch : s) {
        if (!inQuote) {
            if (ch == '\'' || ch == '"') {
                inQuote = true;
                quoteChar = ch;
                cur.clear();
            }
        } else {
            if (ch == quoteChar) {
                tokens.push_back(cur);
                cur.clear();
                inQuote = false;
                quoteChar = 0;
            } else {
                cur += ch;
            }
        }
    }
    return tokens;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string input, line;
    while (getline(cin, line)) {
        if (!input.empty()) input += '\n';
        input += line;
    }

    vector<string> tokens = extractQuotedTokens(input);

    AllOne obj;
    vector<string> ans;

    for (size_t i = 0; i < tokens.size();) {
        string op = tokens[i++];

        if (op == "inc") {
            if (i < tokens.size()) obj.inc(tokens[i++]);
            ans.push_back("null");
        } else if (op == "dec") {
            if (i < tokens.size()) obj.dec(tokens[i++]);
            ans.push_back("null");
        } else if (op == "getMaxKey") {
            ans.push_back("'" + obj.getMaxKey() + "'");
        } else if (op == "getMinKey") {
            ans.push_back("'" + obj.getMinKey() + "'");
        }
    }

    cout << "[";
    for (size_t i = 0; i < ans.size(); ++i) {
        if (i) cout << ",";
        cout << ans[i];
    }
    cout << "]";

    return 0;
}
